package com.aip.companion
import android.app.*;import android.content.*;import android.net.Uri;import android.os.Bundle;import android.provider.Settings;import android.view.*;import android.widget.*
class MainActivity:Activity(){private val q=OutgoingQueue();override fun onCreate(b:Bundle?){super.onCreate(b);getSystemService(NotificationManager::class.java).createNotificationChannel(NotificationChannel("status","Status do AIP",NotificationManager.IMPORTANCE_LOW));val box=LinearLayout(this);box.orientation=LinearLayout.VERTICAL;box.setPadding(24,24,24,24);box.addView(TextView(this).apply{text="AIP Companion\nModo independente/offline";textSize=22f});val status=TextView(this).apply{text="Histórico local somente leitura\nTransporte: aguardando desktop"};box.addView(status);val input=EditText(this).apply{hint="Mensagem curta";maxLines=3};box.addView(input);box.addView(Button(this).apply{text="Pré-visualizar";setOnClickListener{try{q.preview(input.text.toString());input.text.clear();status.text="Mensagem aguardando aprovação (fila ${q.size()})"}catch(_:Exception){status.text="Mensagem fora do limite"}}});box.addView(Button(this).apply{text="Aprovar quando conectado";setOnClickListener{status.text=if(q.approve()==null)"Fila vazia" else "Aprovada; desktop não conectado"}});box.addView(Button(this).apply{text="Cancelar pendente";setOnClickListener{q.cancel();status.text="Item cancelado"}});box.addView(Button(this).apply{text="Ativar ícone flutuante";setOnClickListener{if(!Settings.canDrawOverlays(this@MainActivity))startActivity(Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:$packageName")))else startService(Intent(this@MainActivity,OverlayService::class.java))}});setContentView(box)}}
